fn cloudVertex(position: vec3<f32>, normal: vec3<f32>, uv: vec2<f32>, instance: u32) -> VertexOut {
    let base = instance * EA_ECS_STRIDE;
    let spot = vec3<f32>(ecs[base + 0u], ecs[base + 1u], ecs[base + 2u]) + position;
    var o: VertexOut;
    o.clipPos = camera.viewProj * vec4<f32>(spot, 1.0);
    o.worldPos = spot;
    o.worldNormal = normal;
    o.uv = uv;
    o.ecsColor = vec3<f32>(0.4 + 0.6 * ecs[base + 3u], 0.7, 1.0);
    return o;
}

fn cloudFragment(input: VertexOut) -> vec4<f32> {
    let sun = normalize(vec3<f32>(0.3, 1.0, 0.2));
    let shade = 0.3 + 0.7 * max(dot(normalize(input.worldNormal), sun), 0.0);
    return vec4<f32>(input.ecsColor * shade, 1.0);
}

fn glintVertex(corner: u32, instance: u32) -> VertexOut {
    let col = f32(instance % 1024u);
    let row = f32(instance / 1024u);
    let angle = f32(corner) * 2.0943951;
    let lift = 2.0 + 0.3 * fract(f32(instance) * 0.618034);
    let spot = vec3<f32>((col - 511.5) * 0.03, lift, (row - 511.5) * 0.03) + vec3<f32>(cos(angle), 0.0, sin(angle)) * 0.01;
    var o: VertexOut;
    o.clipPos = camera.viewProj * vec4<f32>(spot, 1.0);
    o.worldPos = spot;
    o.worldNormal = vec3<f32>(0.0, 1.0, 0.0);
    o.uv = vec2<f32>(0.5);
    o.ecsColor = vec3<f32>(1.0, 0.85, 0.5) + vec3<f32>(ecs[instance * EA_ECS_STRIDE]);
    return o;
}

fn glintFragment(input: VertexOut) -> vec4<f32> {
    return vec4<f32>(input.ecsColor, 1.0);
}

fn seedMotes(index: u32) {
    let base = index * B_motes_STRIDE;
    let col = f32(index % 1024u);
    let row = f32(index / 1024u);
    b_motes[base + 0u] = (col - 511.5) * 0.03;
    b_motes[base + 1u] = 0.5 * sin(col * 0.05) * cos(row * 0.05);
    b_motes[base + 2u] = (row - 511.5) * 0.03;
    b_motes[base + 3u] = fract(col * 0.37 + row * 0.11);
}
